    assert EXTRACTION_CONTRACT.tier == 'LLM-LED'; assert all((roadmap[ac_id].proof_kind != 'exact' for ac_id in ('AC-extraction.1.1', 'AC-extraction.5.7', 'AC-extraction.5.19')))
